def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product obtainable by inserting K multiplication signs into the
    numeric string `num_str` of length N. The string is split into K+1 contiguous parts,
    each part interpreted as an integer, and the product of these integers is computed.
    If the input is invalid or the number of splits is impossible, the function returns 0.
    """
    try:
        # Basic validation
        if not isinstance(num_str, str) or not isinstance(N, int) or not isinstance(K, int):
            return 0
        if N != len(num_str) or N <= 0 or K < 0:
            return 0
        if K > N - 1:
            return 0

        # Special case: no splits
        if K == 0:
            return int(num_str)

        # DP table: dp[i][k] = maximum product for prefix of length i with k splits
        dp = [[0] * (K + 1) for _ in range(N + 1)]

        # Base case: no splits, product is the integer value of the prefix
        for i in range(1, N + 1):
            dp[i][0] = int(num_str[:i])

        # Fill DP table
        for k in range(1, K + 1):
            # At least k+1 digits are needed to have k splits
            for i in range(k + 1, N + 1):
                best = 0
                # j is the start index of the last segment
                for j in range(k, i):
                    segment_value = int(num_str[j:i])
                    candidate = dp[j][k - 1] * segment_value
                    if candidate > best:
                        best = candidate
                dp[i][k] = best

        return dp[N][K]
    except Exception:
        # In case of any unexpected error, return 0 as a safe fallback
        return 0

def calculate_scholarship(grades: List[int], leader: str, west: str, papers: int) -> int:
